/// The extension-panel relay factory (issue #34 item 1): when this build
/// runs inside the browser extension panel (a `chrome.runtime.id` page),
/// the chat is served by the service-worker agent over the worker relay —
/// the UI holds no keys and gains the SW's browser tools. Null for plain
/// web/desktop, which keeps the local [AgentService.create] path.
///
/// The host is decided by [decideRelay]: the build flag
/// (`--dart-define=FA_HOST=extension`, set by `build_browser_ext.sh
/// --with-app`) wins over the runtime probe, and the decision + reason are
/// ALWAYS logged — a silent fallthrough here once cost a debugging session
/// ("extension panel, but the local web agent answered").
Future<RelayAgentService?> createRelayServiceIfHosted() async {
  final decision = decideRelay(buildHost: kFaBuildHost, probe: isExtensionHost);
  debugPrint('[fah] relay probe: ${decision.reason}');
  if (!decision.hosted) return null;
  final relay = await RelayAgentService.create();
  debugPrint(
    relay == null
        ? '[fah] relay: hosted, but no port channel (SW unreachable?)'
        : '[fah] relay: worker transport created',
  );
  return relay;
}

Future<void> main() => const FaAppBoot(routes: bootAppRoutes).run();

/// The routes stage: mounts [MyApp] and attaches the OpenRouter OAuth
/// listeners. Lives beside [MyApp] — the boot module (issue #483) stays
/// UI-free.
Future<void> bootAppRoutes(
  BootStores stores,
  FirebaseAnalytics? analytics,
) async {
  debugPrint('[fah] starting runApp');
  runApp(
    MyApp(
      env: stores.env,
      registry: stores.registry,
      lastConnectionStore: stores.lastConnection,
      themeController: stores.themeController,
      themePackStore: stores.themePacks,
      onboardingStore: stores.onboarding,
      skillsAccessStore: stores.skillsAccess,
      sessionKeysStore: stores.sessionKeys,
      mediaModelsStore: stores.mediaModels,
      taskModelsStore: stores.taskModels,
      onDeviceConfigStore: stores.onDeviceConfig,
      imagePreviewStore: stores.imagePreviews,
      networkMode: stores.networkMode,
      networkSessions: stores.networkSessions,
      analytics: analytics,
    ),
  );
  // Attach deep-link (mobile) and postMessage (web) listeners for the
  // OpenRouter OAuth callback. This is fire-and-forget: the coordinator
  // singleton forwards codes to any in-flight settings-sheet flow.
  unawaited(attachOpenRouterOAuthLinks());
  _exchangeOpenRouterWebRedirect(stores.sessionKeys);
}

/// On mobile web (iOS Safari / PWA) the popup cannot reliably hand the code
/// back, so OpenRouter redirects to the app URL with `?code=...&state=...`.
/// Exchange it after the first frame and persist the key.
void _exchangeOpenRouterWebRedirect(SessionKeysStore sessionKeys) {
  if (!kIsWeb) return;
  WidgetsBinding.instance.addPostFrameCallback((_) async {
    final key = await completeOpenRouterOAuthFromRedirect();
    await _saveOpenRouterRedirectKey(sessionKeys, key);
  });
}

/// Persists a redirect-carried key; blank/absent redirects are ignored
/// (gh-1848 split).
Future<void> _saveOpenRouterRedirectKey(
  SessionKeysStore sessionKeys,
  String? key,
) async {
  if (key == null || key.isEmpty) return;
  await sessionKeys.set('OPENROUTER_API_KEY', key);
  debugPrint('[Fa] OpenRouter key saved from redirect');
}

class MyApp extends StatelessWidget {
  const MyApp({
    super.key,
    this.env,
    this.registry,
    this.lastConnectionStore,
    this.themeController,
    this.themePackStore,
    this.onboardingStore,
    this.skillsAccessStore,
    this.sessionKeysStore,
    this.mediaModelsStore,
    this.taskModelsStore,
    this.onDeviceConfigStore,
    this.chatTextStore,
    this.imagePreviewStore,
    this.webLlmEngine,
    this.gemmaEngine,
    this.transformersJsEngine,
    this.analytics,
    this.networkMode,
    this.networkSessions,
  });

  /// The shared execution env; `null` lets [AgentService.create] build the
  /// platform one (tests never reach that path).
  final ExecutionEnv? env;

  /// The persisted custom-provider registry; `null` falls back to an
  /// in-memory one (tests).
  final ProviderRegistry? registry;

  /// The persisted last-connection store; `null` skips prefill and
  /// persistence (tests).
  final LastConnectionStore? lastConnectionStore;

  /// The persisted appearance choice; `null` falls back to a shared
  /// in-memory controller defaulting to [FahThemeMode.system] (tests).
  final ThemeController? themeController;

  /// The installed theme packs; `null` skips the scope (the settings themes
  /// section hides and the stock look stays, tests).
  final ThemePackStore? themePackStore;

  /// The persisted first-launch onboarding flag; `null` skips onboarding
  /// entirely (tests, and any host that never shows it).
  final OnboardingStore? onboardingStore;

  /// The persisted third-party skills consent store; `null` skips the
  /// one-time boot dialog (tests).
  final SkillsAccessStore? skillsAccessStore;

  /// The persisted saved-keys store; `null` skips the scope (the settings
  /// Keys section and form prefill hide, tests).
  final SessionKeysStore? sessionKeysStore;

  /// The persisted media-model overrides store; `null` skips the scope (the
  /// settings Media models section hides, tests).
  final MediaModelsStore? mediaModelsStore;

  /// The persisted task-model overrides store; `null` skips the scope (the
  /// settings Task models section hides, tests).
  final TaskModelsStore? taskModelsStore;

  /// The on-device engines the user configured (drives Providers rows); null
  /// skips the scope (tests).
  final OnDeviceConfigStore? onDeviceConfigStore;

  /// The persisted chat text-size choice; `null` skips the scope (the
  /// settings Chat text section hides, transcripts render at the default).
  final ChatTextStore? chatTextStore;

  /// The persisted "High-quality image previews" choice (issue #207);
  /// `null` skips the scope (the settings section hides, previews stay
  /// downscaled — the default).
  final ImagePreviewStore? imagePreviewStore;

  /// Engine overrides for the on-device providers (tests); default to the
  /// platform singletons.
  final WebLlmEngineApi? webLlmEngine;
  final GemmaEngineApi? gemmaEngine;
  final TransformersJsEngineApi? transformersJsEngine;

  /// Firebase Analytics instance; null when Firebase is not initialized
  /// (e.g., tests or placeholder firebase_options.dart).
  final FirebaseAnalytics? analytics;

  /// The network-mode state machine (issue #955); null disables network
  /// mode entirely (tests, hosts that never boot the network stores) and
  /// the home renders exactly the classic local tree.
  final NetworkModeController? networkMode;

  /// The fa_network session manager (issue #955); must accompany
  /// [networkMode].
  final NetworkSessionManager? networkSessions;

  /// Fallback for [themeController] when none is injected (tests): a single
  /// shared in-memory controller so every [MyApp] build sees the same one.
  static final ThemeController _fallbackThemeController =
      ThemeController.inMemory();
  @override
  Widget build(BuildContext context) {
    final theme = _resolvedThemeController;
    Widget child = _themeListenable(theme);
    return _wrapScopes(theme, child);
  }

  /// The controller this [MyApp] renders with: the injected one, or the
  /// shared in-memory fallback (tests).
  ThemeController get _resolvedThemeController =>
      themeController ?? _fallbackThemeController;

  /// The theme/branding reactive subtree (the [MaterialApp] inside).
  Widget _themeListenable(ThemeController theme) {
    final packs = themePackStore;
    return ListenableBuilder(
      listenable: packs == null ? theme : Listenable.merge([theme, packs]),
      builder: (context, _) {
        // The active theme pack (null → stock look). Stale ids (pack
        // removed elsewhere) resolve to the stock FaUiTheme, never a crash.
        final uiTheme = packs?.byId(theme.packId)?.spec.toFaUiTheme();
        return FaUiThemeProvider(
          data: uiTheme ?? const FaUiTheme(),
          child: _materialApp(theme, uiTheme),
        );
      },
    );
  }

  Widget _materialApp(ThemeController theme, FaUiTheme? uiTheme) {
    return MaterialApp(
      title: 'Fa',
      theme: buildFahThemeLight(uiTheme: uiTheme),
      darkTheme: buildFahTheme(uiTheme: uiTheme),
      themeMode: theme.themeMode,
      localizationsDelegates: AppLocalizations.localizationsDelegates,
      supportedLocales: AppLocalizations.supportedLocales,
      // Some embedded browsers (CI containers, stripped webviews)
      // report an EMPTY navigator.language; resolving through intl
      // then throws "Incorrect locale information provided" and the
      // app never boots. Fall back to English for a bogus device
      // locale.
      localeResolutionCallback: (deviceLocale, supported) =>
          resolveAppLocale(deviceLocale),
      navigatorObservers: analytics != null
          ? [FirebaseAnalyticsObserver(analytics: analytics!)]
          : const <NavigatorObserver>[],
      // macOS desktop: the unified titlebar's traffic lights float
      // over Flutter content (fullSizeContentView). The content fills
      // the ENTIRE window — each screen handles its own
      // traffic-light clearance. A transparent drag strip overlays
      // the top so the window can still be moved.
      builder: _navigatorBuilder,
      home: BootstrapScreen(
        env: env,
        registry: registry,
        lastConnectionStore: lastConnectionStore,
        onboardingStore: onboardingStore,
        skillsAccessStore: skillsAccessStore,
        sessionKeysStore: sessionKeysStore,
        taskModelsStore: taskModelsStore,
        webLlmEngine: webLlmEngine,
        gemmaEngine: gemmaEngine,
        transformersJsEngine: transformersJsEngine,
        networkMode: networkMode,
        networkSessions: networkSessions,
      ),
    );
  }

  Widget _navigatorBuilder(BuildContext context, Widget? navigatorChild) {
    if (kIsWeb || defaultTargetPlatform != TargetPlatform.macOS) {
      return _plainNavigatorChild(navigatorChild);
    }
    return Stack(
      children: [
        Positioned.fill(child: _plainNavigatorChild(navigatorChild)),
        // Transparent drag strip for window movement.
        const Positioned(
          top: 0,
          left: 0,
          right: 0,
          height: 28,
          child: _MacOSDragStrip(),
        ),
      ],
    );
  }

  Widget _plainNavigatorChild(Widget? navigatorChild) =>
      navigatorChild ?? const SizedBox.shrink();

  /// The scope wrappers over the optional stores: every present store gets
  /// its InheritedWidget down the tree.
  Widget _wrapScopes(ThemeController theme, Widget child) {
    child = FahThemeScope(controller: theme, child: child);
    return _wrapPreviewScopes(_wrapModelScopes(_wrapCoreScopes(child)));
  }

  Widget _wrapCoreScopes(Widget child) {
    final packs = themePackStore;
    final sessionKeys = sessionKeysStore;
    final onDeviceConfig = onDeviceConfigStore;
    if (packs != null) {
      child = ThemePackScope(store: packs, child: child);
    }
    if (sessionKeys != null) {
      child = SessionKeysScope(store: sessionKeys, child: child);
    }
    if (onDeviceConfig != null) {
      child = OnDeviceConfigScope(store: onDeviceConfig, child: child);
    }
    return child;
  }

  Widget _wrapModelScopes(Widget child) {
    final mediaModels = mediaModelsStore;
    final taskModels = taskModelsStore;
    if (mediaModels != null) {
      child = MediaModelsScope(store: mediaModels, child: child);
    }
    if (taskModels != null) {
      child = TaskModelsScope(store: taskModels, child: child);
    }
    return child;
  }

  Widget _wrapPreviewScopes(Widget child) {
    final chatText = chatTextStore;
    final imagePreviews = imagePreviewStore;
    if (chatText != null) {
      child = ChatTextScope(store: chatText, child: child);
    }
    if (imagePreviews != null) {
      child = ImagePreviewScope(store: imagePreviews, child: child);
    }
    return child;
  }
}

/// A transparent 28px strip at the top of the macOS window that allows
/// dragging the window. The traffic lights float over this area (they're
/// drawn by the OS); the strip's only job is to register drag gestures.
class _MacOSDragStrip extends StatelessWidget {
  const _MacOSDragStrip();

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onPanStart: (_) {
        // Trigger native window drag.
      },
      child: const SizedBox.expand(),
    );
  }
}

/// The app home after a successful connect: on wide screens (≥900px) the
/// [WideLayoutShell] (sidebar + content area), otherwise the [AppLauncherScreen]
/// with the floating session chat sheet.
Widget faHomeScreen({
  required BuildContext context,
  required FlutterSessionManager manager,
  ProviderRegistry? registry,
  LastConnectionStore? lastConnectionStore,
  SessionNamesStore? sessionNamesStore,
  UploadPicker? uploadPicker,
  AsrApi? asr,
  AsrTranscriber? asrTranscriber,
  SandboxAudioControllerFactory? audioControllerFactory,
  SandboxVideoControllerFactory? videoControllerFactory,
  TileEngineFactory? tileEngineFactory,
  LauncherLayoutStore? layoutStore,
  AppsStore? appsStore,

  /// Network mode (issue #955): the WIDE home never swaps — the
  /// [WideLayoutShell] consumes the mode internally (sidebar shows the
  /// networks list, the center the network surface). The NARROW home
  /// swaps to [NetworkHomePage] when the controller says
  /// [AppMode.network] (the mobile list → channels → chat navigation
  /// pattern). When absent (tests, non-network hosts) the home is
  /// byte-identical to the classic local tree (AC-N1).
  NetworkModeController? networkMode,
  NetworkSessionManager? networkSessions,

  /// Restore the persisted apps↔chat surface mode on the narrow home
  /// (issue #224): true for the real production homes, false in tests.
  bool restoreAppsMode = false,
}) {
  final isWide = MediaQuery.sizeOf(context).width >= kWideLayoutBreakpoint;
  // The classic local home — built exactly as before; the network gate
  // below swaps the WHOLE surface, never the local tree's structure.
  final localHome = WidgetPublicationResumeRefresher(
    env: manager.env,
    child: isWide
        ? WideLayoutShell(
            manager: manager,
            registry: registry,
            lastConnectionStore: lastConnectionStore,
            sessionNamesStore: sessionNamesStore,
            uploadPicker: uploadPicker,
            asr: asr,
            asrTranscriber: asrTranscriber,
            audioControllerFactory: audioControllerFactory,
            videoControllerFactory: videoControllerFactory,
            tileEngineFactory: tileEngineFactory,
            layoutStore: layoutStore,
            appsStore: appsStore,
            networkMode: networkMode,
            networkSessions: networkSessions,
          )
        : AppLauncherScreen(
            manager: manager,
            registry: registry,
            lastConnectionStore: lastConnectionStore,
            sessionNamesStore: sessionNamesStore,
            uploadPicker: uploadPicker,
            asr: asr,
            asrTranscriber: asrTranscriber,
            audioControllerFactory: audioControllerFactory,
            videoControllerFactory: videoControllerFactory,
            tileEngineFactory: tileEngineFactory,
            layoutStore: layoutStore,
            appsStore: appsStore,
            restoreAppsMode: restoreAppsMode,
            networkMode: networkMode,
            networkSessions: networkSessions,
          ),
  );
  final mode = networkMode;
  final sessions = networkSessions;
  // Wide: the shell consumes the mode internally (sidebar/center swap in
  // place) — the full-tree swap is the NARROW pattern only.
  if (mode == null || sessions == null || isWide) return localHome;
  return ListenableBuilder(
    listenable: mode,
    builder: (context, _) => mode.mode == AppMode.network
        ? NetworkHomePage(controller: mode, manager: sessions)
        : localHome,
  );
}

/// Boot decision screen: the setup form shows only when nothing was ever
/// configured (first run) or the last connection cannot be restored (its
/// key is gone, or it was an on-device model — those re-offer the quick
/// start instead of silently loading multi-GB weights at boot). A
/// restorable last connection goes straight to chat.
///
/// First launch (no restorable connection AND the onboarding flag unseen,
/// see [OnboardingStore]) shows the [OnboardingScreen] first; completing or
/// skipping it sets the flag and boot continues — a model preset applied
/// during onboarding persists a restorable connection, so boot re-evaluates
/// and can go straight to chat.
class BootstrapScreen extends StatefulWidget {
  const BootstrapScreen({
    super.key,
    this.env,
    this.registry,
    this.lastConnectionStore,
    this.onboardingStore,
    this.skillsAccessStore,
    this.sessionKeysStore,
    this.taskModelsStore,
    this.webLlmEngine,
    this.gemmaEngine,
    this.transformersJsEngine,
    this.networkMode,
    this.networkSessions,
  });

  /// The shared execution env handed to [AgentService.create].
  final ExecutionEnv? env;

  /// The persisted custom-provider registry (its keys ride the Keychain on
  /// iOS/macOS — that is what makes a hosted auto-connect possible).
  final ProviderRegistry? registry;

  /// The persisted last-connection record being restored.
  final LastConnectionStore? lastConnectionStore;

  /// The persisted first-launch onboarding flag; `null` never shows
  /// onboarding (tests).
  final OnboardingStore? onboardingStore;

  /// The persisted third-party skills consent store; when onboarding was
  /// already seen and no consent is recorded, the boot flow asks once
  /// (non-blocking, after the first frame). `null` never asks (tests).
  final SkillsAccessStore? skillsAccessStore;

  /// The persisted saved-keys store (hosted key resolution).
  final SessionKeysStore? sessionKeysStore;

  /// The persisted task-model overrides store, passed to [AgentService.create].
  final TaskModelsStore? taskModelsStore;

  /// Engine overrides for the on-device providers (tests).
  final WebLlmEngineApi? webLlmEngine;
  final GemmaEngineApi? gemmaEngine;
  final TransformersJsEngineApi? transformersJsEngine;

  /// Network mode (issue #955), forwarded to [faHomeScreen].
  final NetworkModeController? networkMode;

  /// The fa_network session manager (issue #955), forwarded with
  /// [networkMode].
  final NetworkSessionManager? networkSessions;

  @override
  State<BootstrapScreen> createState() => _BootstrapScreenState();
}

class _BootstrapScreenState extends State<BootstrapScreen> {
  /// The connection being restored; null renders the setup form directly
  /// (no navigation, so the first frame already shows it).
  AgentConfig? _config;

  /// Set once the onboarding flow finishes (completed or skipped) so the
  /// boot continues to the setup form or the auto-connect.
  var _onboardingDone = false;

  /// The boot-time read of the third-party skills consent (started in
  /// [initState], so the dialog never waits on disk). Discovery is ON by
  /// default — the dialog fires only for an explicit `ask` choice (Settings),
  /// never on a fresh install.
  Future<SkillsAccess?>? _skillsAccessFuture;

  /// First-launch onboarding shows only when nothing can be restored
  /// (upgraders with a saved connection never see it) and the persisted
  /// flag is still unseen.
  bool get _showOnboarding {
    final store = widget.onboardingStore;
    return !_onboardingDone && _config == null && store != null && !store.seen;
  }

  @override
  void initState() {
    super.initState();
    // Extension panel (issue #34): the SW owns providers, config and the
    // session — local onboarding/restore paths never apply, whatever they
    // persisted on previous builds.
    if (isExtensionHost()) {
      debugPrint('[fah] extension host detected: booting the SW relay');
      _onboardingDone = true;
      WidgetsBinding.instance.addPostFrameCallback(
        (_) => unawaited(_bootRelay()),
      );
      return;
    }
    _config = restorableBootConfig(
      connection: widget.lastConnectionStore?.connection,
      registry: widget.registry,
      sessionKeysStore: widget.sessionKeysStore,
    );
    // The skills-consent dialog fires only for an EXPLICIT `ask` choice
    // (Settings) — discovery is on by default, so a fresh install never
    // sees it. Mobile never asks: the third-party roots don't exist there.
    final onboarding = widget.onboardingStore;
    final skillsStore = widget.skillsAccessStore;
    if (skillsConsentSurfacesVisible &&
        onboarding != null &&
        onboarding.seen &&
        skillsStore != null) {
      _skillsAccessFuture = skillsStore.load();
      if (_config == null) {
        // No navigation ahead (the empty-manager home renders in place) —
        // ask right after the first frame, never blocking the build.
        WidgetsBinding.instance.addPostFrameCallback(
          (_) => unawaited(_maybeAskSkillsAccess(context)),
        );
      }
    }
    if (_config != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) => unawaited(_boot()));
    }
  }

  /// Shows the third-party skills consent dialog when the user explicitly
  /// chose "ask" in Settings. Allow persists `granted`; Not now persists
  /// `denied` (a boot-dialog answer must stick or the dialog would fire on
  /// every launch); a dismissed dialog stays `ask` and asks again next
  /// launch. Boot is never blocked on it.
  Future<void> _maybeAskSkillsAccess(BuildContext dialogContext) async {
    final future = _skillsAccessFuture;
    final store = widget.skillsAccessStore;
    if (future == null || store == null) return;
    _skillsAccessFuture = null;
    if (await future != SkillsAccess.ask) return; // only an explicit "ask"
    if (!dialogContext.mounted) return;
    AppAnalytics.instance.screenOpened('skills_access_dialog');
    final allow = await showDialog<bool>(
      context: dialogContext,
      builder: (context) => AlertDialog(
        title: Text(context.l10n.skillsAccessDialogTitle),
        content: Text(context.l10n.skillsAccessDialogBody),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: Text(context.l10n.skillsAccessNotNow),
          ),
          FilledButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: Text(context.l10n.skillsAccessAllow),
          ),
        ],
      ),
    );
    if (allow == null) return; // dismissed — ask again next launch
    final access = allow ? SkillsAccess.granted : SkillsAccess.denied;
    AppAnalytics.instance.skillsAccessChanged(access.name);
    await store.save(access);
  }

  /// Extension-panel boot: connect to the service-worker agent and go
  /// straight to chat — no provider form (the SW's chrome.storage config
  /// is edited in Settings, which round-trips `settings_put`), no local
  /// session store. The orchestration lives in the boot module
  /// ([bootExtensionRelay]); this wrapper owns the widget shell —
  /// navigation and `mounted`-guarded error state.
  Future<void> _bootRelay() async {
    try {
      // gh-1507: same restore-phase coverage as [_boot] — the SW relay
      // restores the session too.
      kBootWatchdog.beginRestore();
      await bootExtensionRelay(
        env: widget.env,
        onHome: (manager, registry) async {
          // The relay restore (attach + converge + registry seed) is done
          // by the time onHome runs — disarm the restore phase BEFORE the
          // home navigation: pushReplacement stays pending for as long as
          // the user sits on home, and bootExtensionRelay awaits onHome, so
          // the finally below cannot disarm a healthy boot until home is
          // popped (spurious "restore not completed" breadcrumbs from 10 s
          // after every launch). The finally stays as the failure-path net
          // (restoreDone is idempotent): a relay boot that threw never
          // reached here.
          kBootWatchdog.restoreDone();
          if (!mounted) return;
          AppAnalytics.instance.bootstrapResult('chat');
          final navigator = Navigator.of(context);
          await navigator.pushReplacement(
            MaterialPageRoute(
              builder: (_) => faHomeScreen(
                context: navigator.context,
                manager: manager,
                registry: registry,
                restoreAppsMode: true,
                networkMode: widget.networkMode,
                networkSessions: widget.networkSessions,
              ),
            ),
          );
        },
        onError: (message) {
          if (mounted) setState(() => _relayError = message);
        },
      );
    } finally {
      kBootWatchdog.restoreDone();
    }
  }

  /// Set when the extension-panel relay could not attach (SW dead/broken
  /// build): the screen shows the error with a retry instead of onboarding.
  String? _relayError;

  Future<void> _boot() async {
    final config = _config!;
    try {
      // gh-1507: arm the watchdog's restore phase for the whole restore
      // chain — a wedge after the first frame (the reported freeze shape)
      // breadcrumbs instead of sitting silent.
      kBootWatchdog.beginRestore();
      BootSteps.begin('restore:env');
      final env = widget.env ?? await createPlatformEnv();
      BootSteps.mark('restore:env');
      BootSteps.begin('restore:manager');
      final manager = FlutterSessionManager(
        env: env,
        sessionsRoot: defaultSessionsRoot(env.sessionCwd),
      );
      BootSteps.mark('restore:manager');
      // Resume the day's session (or an untouched empty one) instead of
      // stacking a fresh empty session on every cold launch.
      BootSteps.begin('restore:session');
      await manager.createOrResumeSession(
        config: config,
        createFactory: () => AgentService.create(
          config: config,
          env: env,
          sessionKeys: widget.sessionKeysStore,
          providerRegistry: widget.registry,
          taskModelsStore: widget.taskModelsStore,
        ),
        openFactory: () => AgentService.create(
          config: config,
          env: env,
          sessionKeys: widget.sessionKeysStore,
          providerRegistry: widget.registry,
          taskModelsStore: widget.taskModelsStore,
        ),
      );
      BootSteps.mark('restore:session');
      // The restore chain is done — disarm the watchdog's restore phase
      // HERE, not in the finally below: `await navigator.pushReplacement`
      // stays pending for as long as the user sits on home, so a
      // finally-disarm would keep the phase armed for the whole session —
      // every healthy launch would breadcrumb "restore not completed"
      // from 10 s after boot (and widget tests that end parked on home
      // would die on the pending restore timer). The finally remains the
      // failure-path net (restoreDone is idempotent): a restore that
      // THREW never reached here and is disarmed on the way out.
      kBootWatchdog.restoreDone();
      if (!mounted) return;
      AppAnalytics.instance.bootstrapResult('chat');
      // Use the Navigator's context, not the State's — after a hot restart
      // the State is defunct but the Navigator's context stays valid.
      final navigator = Navigator.of(context);
      final navigatorContext = navigator.context;
      await navigator.pushReplacement(
        MaterialPageRoute(
          builder: (_) => faHomeScreen(
            context: navigatorContext,
            manager: manager,
            registry: widget.registry,
            lastConnectionStore: widget.lastConnectionStore,
            restoreAppsMode: true,
            networkMode: widget.networkMode,
            networkSessions: widget.networkSessions,
          ),
        ),
      );
      // The skills-consent dialog (undecided upgraders) rides above the
      // freshly pushed home — the BootstrapScreen state is defunct by now,
      // so the Navigator's context is the valid one.
      if (navigatorContext.mounted) {
        unawaited(_maybeAskSkillsAccess(navigatorContext));
      }
    } on Object catch (error, stack) {
      // A failed restore (endpoint down, key rejected) lands on the setup
      // form — prefilled by the same last-connection record. Log it: a
      // silent catch here used to leave the boot spinner up forever with
      // no clue why.
      debugPrint('[fah] boot restore failed: $error\n$stack');
      if (mounted) {
        AppAnalytics.instance.bootstrapResult('setup_restore_failed');
        setState(() => _config = null);
      }
    } finally {
      // gh-1507: failure-path net for the restore phase (restoreDone is
      // idempotent — the success path already disarmed above, before the
      // home navigation). A restore that THREW — landing on the setup
      // form, no wedge — is disarmed here on the way out.
      kBootWatchdog.restoreDone();
    }
  }

  /// Lands the user on the home screen with an empty manager after
  /// onboarding (no provider applied during the walkthrough) — the
  /// launcher's empty state prompts them to open Settings → Providers
  /// rather than dumping them back into the legacy "Connect to Fa"
  /// form they just left.
  Widget _buildHomeWithEmptyManager() {
    AppAnalytics.instance.setupShown('onboarding_done_no_provider');
    return _EmptyManagerHome(
      env: widget.env,
      registry: widget.registry,
      lastConnectionStore: widget.lastConnectionStore,
      networkMode: widget.networkMode,
      networkSessions: widget.networkSessions,
    );
  }

  Widget _buildSetupScreen() {
    AppAnalytics.instance.setupShown(
      widget.lastConnectionStore?.connection != null
          ? 'restore_unavailable'
          : 'first_run',
    );
    return SetupScreen(
      env: widget.env,
      registry: widget.registry,
      lastConnectionStore: widget.lastConnectionStore,
      sessionKeysStore: widget.sessionKeysStore,
      webLlmEngine: widget.webLlmEngine,
      gemmaEngine: widget.gemmaEngine,
      transformersJsEngine: widget.transformersJsEngine,
      networkMode: widget.networkMode,
      networkSessions: widget.networkSessions,
    );
  }

  Widget _buildOnboardingScreen() {
    return OnboardingScreen(
      onboardingStore: widget.onboardingStore,
      registry: widget.registry,
      lastConnectionStore: widget.lastConnectionStore,
      onFinished: ({required bool skipped}) => _onboardingFinished(),
    );
  }

  /// The onboarding flow ended (completed or skipped — the screen already
  /// persisted the seen flag). A model preset applied during onboarding
  /// saves a restorable last connection, so boot re-evaluates: restorable →
  /// auto-connect, otherwise the setup form.
  void _onboardingFinished() {
    final config = restorableBootConfig(
      connection: widget.lastConnectionStore?.connection,
      registry: widget.registry,
      sessionKeysStore: widget.sessionKeysStore,
    );
    setState(() {
      _onboardingDone = true;
      _config = config;
    });
    if (config != null) unawaited(_boot());
  }

  @override
  Widget build(BuildContext context) {
    final config = _config;
    if (config != null) return _bootSpinner;
    return _buildWaiting(context);
  }

  /// The shared boot spinner (restoring a connection, extension relay
  /// booting).
  Widget get _bootSpinner => const Scaffold(
    body: Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          FaBrandTile(size: 48),
          SizedBox(height: 24),
          CircularProgressIndicator(),
        ],
      ),
    ),
  );

  /// No restorable connection: wait for the relay (extension hosts) or
  /// render the unconfigured surfaces.
  Widget _buildWaiting(BuildContext context) {
    // Extension panel with an unreachable service worker: retry in place,
    // never fall back to the local provider/onboarding flow.
    if (isExtensionHost() && _relayError == null) return _bootSpinner;
    if (_relayError != null) return _buildRelayError(context);
    return _buildUnconfiguredScreen();
  }

  /// The relay error with an in-place retry — the SW is the only way
  /// forward on an extension panel.
  Widget _buildRelayError(BuildContext context) {
    return Scaffold(
      body: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const FaBrandTile(size: 48),
            const SizedBox(height: 16),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 24),
              child: Text(_relayError!, textAlign: TextAlign.center),
            ),
            const SizedBox(height: 16),
            FilledButton(
              onPressed: () {
                setState(() => _relayError = null);
                _bootRelay();
              },
              child: Text(context.l10n.bootstrapRetry),
            ),
          ],
        ),
      ),
    );
  }

  /// Nothing to restore: onboarding (first launch), the post-onboarding
  /// home with an empty manager, or the legacy setup form.
  Widget _buildUnconfiguredScreen() {
    if (_showOnboarding) return _buildOnboardingScreen();
    // After onboarding (seen flag set) the user has already walked
    // through the provider-first flow. Land them on the home screen
    // with an empty manager — the launcher's empty-state prompts
    // them to open Settings → Providers — rather than dumping them
    // back into the legacy "Connect to Fa" form. The pre-onboarding
    // (onboardingStore == null) path keeps the legacy SetupScreen
    // for upgraders / first-launch-without-onboarding.
    if (widget.onboardingStore != null) {
      return _buildHomeWithEmptyManager();
    }
    return _buildSetupScreen();
  }
}

/// Home with an empty session manager (post-onboarding, no provider yet).
///
/// The env + manager + placeholder session are created ONCE in [initState]:
/// the previous FutureBuilder-in-build version minted a new manager and a
/// new session future on every rebuild (duplicate sessions stacked up) and
/// showed an infinite spinner when session creation failed (a FutureBuilder
/// error has no data). Errors now surface with a retry.
class _EmptyManagerHome extends StatefulWidget {
  const _EmptyManagerHome({
    this.env,
    this.registry,
    this.lastConnectionStore,
    this.networkMode,
    this.networkSessions,
  });

  final ExecutionEnv? env;
  final ProviderRegistry? registry;
  final LastConnectionStore? lastConnectionStore;

  /// Network mode (issue #955), forwarded to [faHomeScreen].
  final NetworkModeController? networkMode;
  final NetworkSessionManager? networkSessions;

  /// A placeholder session so the home never lands empty: user always has
  /// an active session, apps render + open, the sessions list shows
  /// something to pick from. The placeholder uses a no-op stream (the LLM
  /// call errors gracefully) — when the user actually connects a provider
  /// via Settings, reconfigure takes over.
  static final placeholderConfig = AgentConfig(
    providerKind: 'openai-completions',
    modelId: 'placeholder',
    baseUrl: '',
    apiKey: '',
  );

  @override
  State<_EmptyManagerHome> createState() => _EmptyManagerHomeState();
}

class _EmptyManagerHomeState extends State<_EmptyManagerHome> {
  FlutterSessionManager? _manager;
  Object? _error;

  @override
  void initState() {
    super.initState();
    unawaited(_start());
  }

  Future<void> _start() async {
    try {
      final env = widget.env ?? await createPlatformEnv();
      final manager = FlutterSessionManager(
        env: env,
        sessionsRoot: defaultSessionsRoot(env.sessionCwd),
      );
      await manager.createSession(
        config: _EmptyManagerHome.placeholderConfig,
        serviceFactory: () => AgentService.create(
          config: _EmptyManagerHome.placeholderConfig,
          env: env,
          providerRegistry: widget.registry,
        ),
      );
      if (!mounted) return;
      setState(() {
        _manager = manager;
        _error = null;
      });
    } on Object catch (error, stack) {
      debugPrint('[fah] empty-manager home failed: $error\n$stack');
      if (mounted) setState(() => _error = error);
    }
  }

  @override
  Widget build(BuildContext context) {
    final manager = _manager;
    if (manager != null) {
      return faHomeScreen(
        context: context,
        manager: manager,
        registry: widget.registry,
        lastConnectionStore: widget.lastConnectionStore,
        restoreAppsMode: true,
        networkMode: widget.networkMode,
        networkSessions: widget.networkSessions,
      );
    }
    final error = _error;
    if (error != null) {
      return Scaffold(
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const FaBrandTile(size: 48),
              const SizedBox(height: 24),
              Text(context.l10n.bootstrapSessionStartError(error)),
              const SizedBox(height: 16),
              FilledButton(
                onPressed: () {
                  setState(() => _error = null);
                  unawaited(_start());
                },
                child: Text(context.l10n.bootstrapRetry),
              ),
            ],
          ),
        ),
      );
    }
    return const Scaffold(
      body: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            FaBrandTile(size: 48),
            SizedBox(height: 24),
            CircularProgressIndicator(),
          ],
        ),
      ),
    );
  }
}

/// First-run screen: bring-your-own-key connection form (see
/// [AgentSettingsForm]) with a one-tap "Downloaded models" quick start above
/// it (see [DownloadedModelsQuickStart]). Keys typed here stay in memory for
/// the session (explicit saving happens in the settings Keys section, see
/// [SessionKeysStore]); saved custom providers persist (see
/// [ProviderRegistry]) and are offered in the picker, and the last
/// successful connection persists (see [LastConnectionStore]) and
/// pre-selects the form.
class SetupScreen extends StatelessWidget {
  const SetupScreen({
    super.key,
    this.env,
    this.registry,
    this.lastConnectionStore,
    this.sessionKeysStore,
    this.webLlmEngine,
    this.gemmaEngine,
    this.transformersJsEngine,
    this.isWeb,
    this.networkMode,
    this.networkSessions,
  });

  /// The shared execution env handed to [AgentService.create].
  final ExecutionEnv? env;

  /// The persisted custom-provider registry shown in the settings form.
  final ProviderRegistry? registry;

  /// The persisted last-connection store: pre-selects the form and is
  /// updated on every successful connect (quick start included).
  final LastConnectionStore? lastConnectionStore;

  /// The persisted saved-keys store: prefills key fields not covered by
  /// `--dart-define` or `.env` (see [SessionKeysStore]).
  final SessionKeysStore? sessionKeysStore;

  /// Engine overrides for the on-device providers (tests); default to the
  /// platform singletons.
  final WebLlmEngineApi? webLlmEngine;
  final GemmaEngineApi? gemmaEngine;
  final TransformersJsEngineApi? transformersJsEngine;

  /// Overrides `kIsWeb` for tests that need to exercise the web provider
  /// picker on a host test platform.
  final bool? isWeb;

  /// Network mode (issue #955), forwarded to [faHomeScreen].
  final NetworkModeController? networkMode;

  /// The fa_network session manager (issue #955), forwarded with
  /// [networkMode].
  final NetworkSessionManager? networkSessions;

  Future<void> _connect(BuildContext context, AgentConfig config) async {
    // An on-device connect marks the engine configured — its provider row
    // appears in the settings list from now on.
    const onDeviceKinds = {
      webLlmProviderKind,
      gemmaProviderKind,
      transformersJsProviderKind,
    };
    if (onDeviceKinds.contains(config.providerKind)) {
      await OnDeviceConfigScope.maybeOf(
        context,
      )?.markConfigured(config.providerKind);
    }
    final resolvedEnv = env ?? await createPlatformEnv();
    final manager = FlutterSessionManager(
      env: resolvedEnv,
      sessionsRoot: defaultSessionsRoot(resolvedEnv.sessionCwd),
    );
    // Inside the extension panel the relay serves the chat (no local
    // agent, no keys in the UI); null keeps the plain-web local path.
    final relay = await createRelayServiceIfHosted();
    if (relay != null) {
      // Issue #327: the mixed-row guard in reconfigure reads these rows.
      relay.providerRegistry = registry;
      // The relay session id is the SW's; the manager only needs a stable
      // key for the tile/active-session bookkeeping. The local session
      // lifecycle below does not apply — the SW owns the JSONL session.
      // A session_new/session_open from ANY surface arrives as an attach
      // broadcast; re-key the slot so active-dots and labels follow. The
      // hostedLiveId notifier is the single selection source every session
      // UI reads (wide sidebar + narrow drawer) — set it FIRST so the
      // rebuild triggered by the rekey already sees the new truth.
      relay.onLiveSessionIdChanged = (newId) {
        manager.hostedLiveId.value = newId;
        manager.rekeyActiveSession(newId);
      };
      manager.addSession(
        relay.relaySessionId.isEmpty ? 'relay' : relay.relaySessionId,
        relay,
      );
      // The hello/attach handshake completes inside
      // RelayAgentService.create — BEFORE the callback above exists — so
      // the boot-time resync fired into the void; converge once now that
      // the slot exists (no-op when the slot is already keyed right).
      final hostedLiveAtBoot = relay.liveSessionId;
      if (hostedLiveAtBoot != null && hostedLiveAtBoot.isNotEmpty) {
        manager.hostedLiveId.value = hostedLiveAtBoot;
        manager.rekeyActiveSession(hostedLiveAtBoot);
      }
    } else {
      await manager.createOrResumeSession(
        config: config,
        createFactory: () => AgentService.create(
          config: config,
          env: env,
          sessionKeys: sessionKeysStore,
          providerRegistry: registry,
        ),
        openFactory: () => AgentService.create(
          config: config,
          env: env,
          sessionKeys: sessionKeysStore,
          providerRegistry: registry,
        ),
      );
    }
    // Connected — remember where we landed for the next boot (non-secret;
    // the key never reaches the store). Saved before navigation: the push
    // below completes only when the chat screen pops, which may be never.
    await lastConnectionStore?.saveFromConfig(config);
    if (!context.mounted) return;
    final navigator = Navigator.of(context);
    await navigator.pushReplacement(
      MaterialPageRoute(
        builder: (_) => faHomeScreen(
          context: navigator.context,
          manager: manager,
          registry: registry,
          lastConnectionStore: lastConnectionStore,
          restoreAppsMode: true,
          networkMode: networkMode,
          networkSessions: networkSessions,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.l10n.setupAppBarTitle)),
      body: Center(
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(16),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 480),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                DownloadedModelsQuickStart(
                  onConnect: (config) => _connect(context, config),
                  webLlmEngine: webLlmEngine,
                  gemmaEngine: gemmaEngine,
                  transformersJsEngine: transformersJsEngine,
                ),
                AgentSettingsForm(
                  registry: registry,
                  initialConnection: lastConnectionStore?.connection,
                  keysStore: sessionKeysStore,
                  webLlmEngine: webLlmEngine,
                  gemmaEngine: gemmaEngine,
                  transformersJsEngine: transformersJsEngine,
                  isWeb: isWeb,
                  onConnect: (config) => _connect(context, config),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

