      ToolResultMessage(
        toolCallId: 'c1',
        toolName: 'bash',
        content: const [TextContent(text: 'file.txt')],
        isError: false,
        timestamp: DateTime.now(),
      ),
    ],
  ),
  'tool result error': _context(
    messages: [
      ToolResultMessage(
        toolCallId: 'c1',
        toolName: 'bash',
        content: const [TextContent(text: 'boom')],
        isError: true,
        timestamp: DateTime.now(),
      ),
    ],
  ),
  'empty tool result': _context(
    messages: [
      ToolResultMessage(
        toolCallId: 'c1',
        toolName: 'bash',
        content: const [],
        isError: false,
        timestamp: DateTime.now(),
      ),
    ],
  ),
};

